<?php
if(!defined('ABSPATH'))exit; final class DSVS_Renderer{public static function error(){return'<p class="dsvs-error">DSVS-Daten momentan nicht verfügbar.</p>';}private static function head($l,$s){return'<header class="dsvs-heading"><h2>'.esc_html($l['name']).'</h2><h3>'.esc_html($s).'</h3></header>';}public static function standings($r,$l){if(!$r)return'<p class="dsvs-notice">Keine Tabelle verfügbar.</p>';ob_start();?><section class="dsvs-block"><?php echo self::head($l,'Tabelle');?><div class="dsvs-table-wrap"><table class="dsvs-table"><tbody><?php foreach($r as$x):?><tr<?php echo DSVS_Parser::owned($x[1])?' class="dsvs-own-team"':'';?>><?php foreach($x as$v):?><td><?php echo esc_html($v);?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section><?php return ob_get_clean();}public static function games($g,$l,$s,$id='',$poll=false){ob_start();?><section<?php echo$id?' id="'.esc_attr($id).'"':'';?> class="dsvs-block"<?php echo$poll?' data-dsvs-league="'.esc_attr($l['key']).'"':'';?>><?php echo self::head($l,$s);?><div class="dsvs-table-wrap"><table class="dsvs-table"><thead><tr><th>Termin</th><th>Heim</th><th>Ergebnis</th><th>Gast</th></tr></thead><tbody><?php foreach($g as$x):?><tr<?php echo DSVS_Parser::owned($x['home'])||DSVS_Parser::owned($x['away'])?' class="dsvs-own-team"':'';?>><td><?php echo esc_html($x['date'].' '.$x['time']);?></td><td><?php echo esc_html($x['home']);?></td><td><?php echo esc_html($x['result']);?></td><td><?php echo esc_html($x['away']);?></td></tr><?php endforeach;?></tbody></table></div></section><?php return ob_get_clean();}}
